NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Micah'

CHAPTERS = {
    1: {
        1: 'Herran sana, joka tuli mooresetilaiselle Miikalle Jootamin, Aahaan ja Hiskian, Juudan kuninkaiden, päivinä, se, mitä hän näki Samariasta ja Jerusalemista.',
        2: 'Kuulkaa, kaikki kansakunnat, ota korviisi, maa, ja kaikki, mitä maassa on. Olkoon Herra Herra todistaja teitä vastaan, Herra pyhästä temppelistään.',
        3: 'Sillä, katso, Herra lähtee paikaltaan, astuu alas ja tallaa maan kukkuloita.',
        4: 'Vuoret sulavat hänen allaan, ja laaksot halkeavat kuin vaha tulen loimussa ja kuin vedet, jotka syöksyvät jyrkännettä alas.',
        5: 'Tämä kaikki tapahtuu Jaakobin rikoksen tähden ja Israelin heimon syntien tähden. Mikä on Jaakobin rikos? Eikö Samaria! Entä mikä Juudan uhrikukkuloiden? Eikö Jerusalem!',
        6: 'Teen Samarian raunioksi kedolle, viinitarhan istutusmaaksi, syöksen laaksoon sen kivet ja paljastan sen perustukset.',
        7: 'Kaikki sen jumalankuvat murskataan, kaikki sen portonpalkat poltetaan tulessa, ja kaikki sen epäjumalankuvat hävitän, sillä portonpalkoista se on ne koonnut, ja portonpalkoiksi pitää niiden jälleen tulla.',
        8: 'Tämän tähden itken ja olen murheellinen, kuljen avojaloin ja alasti, vaikeroin kuin sakaalit ja valitan kuin strutsit.',
        9: 'Sillä parantumaton on sen haava. Se ulottuu Juudaan asti, se on saavuttanut kansani portin ja on tullut aina Jerusalemiin asti.',
        10: 'Älkää ilmoittako sitä Gatissa, älkää, älkää itkekö. Kieriskelen tuhkassa Beet-Leafrassa.',
        11: 'Mene matkoihisi, Saafirin asujatar, häpeällisesti paljastettuna! Saananin asujatar ei lähde. Beet-Eselin valitus ei anna teidän siihen pysähtyä.',
        12: 'Onnea odottaa tuskaisesti Maarotin asujatar; sillä onnettomuus tulee Herralta Jerusalemin portille.',
        13: 'Valjasta hevoset vaunujen eteen, Laakiin asujatar. Sieltä on alku tytär Siionin syntiin, sillä sinusta löydettiin Israelin rikokset.',
        14: 'Sen tähden annat eron Mooreset-Gatille. Aksibin talot tulevat olemaan pettymys Israelin kuninkaille.',
        15: 'Tuon vielä perijän sinulle, Maaresan asujatar. Adullamiin asti menee Israelin kunnia.',
        16: 'Aja ja keritse pääsi paljaaksi lasten tähden, jotka olivat ilosi. Aja pääsi leveälti paljaaksi, kuten on korppikotkalla, sillä he menevät luotasi pois karkotukseen.',
    },
    2: {
        1: 'Voi niitä, jotka miettivät vääryyttä ja valmistelevat pahaa vuoteillaan! Aamun valjettua he sen tekevät, sillä siihen heillä on valta.',
        2: 'He himoitsevat peltoja ja ryöstävät ne, ja taloja, ja anastavat ne. He sortavat miestä ja hänen taloaan, miestä ja hänen perintöosaansa.',
        3: 'Sen tähden, näin sanoo Herra: Katso, mietin tätä sukua vastaan onnettomuutta, josta ette saa irti niskaanne ettekä voi kävellä ylpeästi, sillä se on oleva paha aika.',
        4: 'Sinä päivänä teistä tehdään sananparsi ja valitetaan surkeasti. Sanotaan: "Olemme aivan hävitetyt, hän on antanut pois kansani perintöosan. Kuinka hän siirtää sen minulta pois ja jakaa peltomme muille!"',
        5: 'Sen tähden sinulla ei ole oleva ketään, joka heittäisi arpaa maaosuudesta Herran seurakunnassa.',
        6: '"Älkää ennustako, ennustajat, älkää sellaista ennustako, ettei teitä kohtaisi häpeä."',
        7: 'Onko tämä Jaakobin heimon puhetta? Onko Herran Henki kärsimätön? Ovatko hänen tekonsa lyhytnäköisiä? Eivätkö hänen sanansa ole hyviä sitä kohtaan, joka vaeltaa suoraan?',
        8: 'Mutta kansani, joka ennen oli minun, on noussut viholliseksi. Vaatteiden päältä te kiskotte viitan niiltä, jotka kulkevat rauhassa ja palaavat sodasta.',
        9: 'Kansani naiset te ajatte pois heidän kodeistaan, jotka ovat heidän ilonsa. Heidän pieniltä lapsiltaan te viette kunniani ainiaaksi.',
        10: 'Nouskaa ja menkää! Sillä tämä ei ole leposija saastutuksen tähden, joka on saanut aikaan tuhon, hirvittävän tuhon.',
        11: 'Jos tulisi tuulen tavoittelija ja valehtelisi petollisuudessaan ja sanoisi: "Saarnaan sinulle viinistä ja väkijuomasta", siinä olisi ennustaja tälle kansalle.',
        12: 'Kokoan sinut kokoamalla, Jaakob, kaikkinesi ja kerään huolella Israelin jäännöksen, saatan heidät yhteen kuin lampaat tarhaan, kuin lauman laitumelleen. On oleva ihmisten kohina!',
        13: 'Tien aukaisija käy heidän edellään. He aukaisevat tiensä, ohittavat portin ja lähtevät siitä ulos. Heidän Kuninkaansa kulkee heidän edellään, ja Herra johdattaa heitä heidän edellään.',
    },
    3: {
        1: 'Sanoin: Kuulkaa, Jaakobin johtajat ja Israelin heimon ruhtinaat! Eikö teidän tulisi tuntea oikeus,',
        2: 'teidän, jotka vihaatte hyvää ja rakastatte pahaa, jotka raastatte ihmisten nahan heidän päältään ja lihan irti heidän luistaan?',
        3: 'He syövät kansani lihan ja nylkevät nahan heidän päältään ja murskaavat heidän luunsa, paloittelevat kuin pataan, kuin lihan kattilaan.',
        4: 'Kun he huutavat Herran puoleen, hän ei vastaa heille, vaan kätkee kasvonsa heiltä sinä aikana, koska he ovat tehneet pahoja tekoja.',
        5: 'Näin sanoo Herra niitä profeettoja vastaan, jotka eksyttävät kansaani ja huutavat: "Rauha!", kun heidän hampaissaan on purtavaa, mutta julistavat pyhän sodan sille, joka ei anna mitään heidän suuhunsa.',
        6: 'Sen tähden teille tulee yö näyistänne, pimeys ennusteluistanne. Aurinko laskee näiltä profeetoilta, ja päivä heiltä pimenee.',
        7: 'Näkijät joutuvat häpeään, ja ennustelijat joutuvat pilkatuiksi. Kaikki he sulkevat suunsa, sillä Jumalan vastausta ei tule.',
        8: 'Mutta minä olen todella täynnä voimaa, Herran Henkeä, tuomiota ja väkevyyttä ilmoittaakseni Jaakobille sen rikokset ja Israelille sen synnit.',
        9: 'Kuulkaa tämä, Jaakobin huoneen johtajat ja Israelin huoneen ruhtinaat, te, jotka halveksitte oikeutta ja vääristätte kaiken suoran,',
        10: 'rakennatte Siionia veritöillä ja Jerusalemia vääryydellä.',
        11: 'Sen johtajat jakavat oikeutta lahjuksia vastaan, sen papit opettavat maksusta, ja sen profeetat ennustelevat rahasta. Mutta Herraan he turvautuvat sanoen: "Eikö Herra ole keskellämme? Ei tule meille onnettomuutta."',
        12: 'Siitä syystä teidän tähtenne Siion kynnetään pelloksi, Jerusalem tulee kiviraunioksi ja temppelivuori metsäiseksi kukkulaksi.',
    },
    4: {
        1: 'On oleva päivien lopulla: Herran temppelin vuori on oleva vahva, kaikkia muita vuoria ylempänä, kukkuloista korkeimpana, ja kaikista pakanakansoista virtaa sinne väkeä solkenaan.',
        2: 'Niin monet pakanakansat lähtevät liikkeelle sanoen: "Tulkaa mukaan, nouskaamme Herran vuorelle, Jaakobin Jumalan huoneeseen, että hän opettaisi meille teitään ja vaeltaisimme hänen polkujaan; sillä Siionista lähtee laki ja Jerusalemista Herran sana."',
        3: 'Hän tuomitsee monien kansakuntien kesken, säätää oikeutta väkeville pakanakansoille kaukaisiin maihin asti. He takovat miekkansa aurankärjiksi ja keihäänsä viinivesoimiksi eikä kansa nosta miekkaa toisiaan vastaan, eivätkä he enää opettele käymään sotia.',
        4: 'He istuvat kukin oman viinipuunsa ja viikunapuunsa alla kenenkään pelottelematta. Sillä Herran Sebaotin suu on puhunut.',
        5: 'Sillä kaikki kansakunnat vaeltavat jumalansa nimessä kukin, mutta me vaellamme Herran, meidän Jumalamme, nimessä aina ja iankaikkisesti.',
        6: 'Sinä päivänä – tämä on Herran sana – tahdon koota ontuvat ja kerätä hajalle ajetut ja ne, joille olin tuottanut onnettomuutta.',
        7: 'Teen ontuvista jäännöksen ja kauas hajotetuista väkevän kansan. Silloin Herra on oleva heidän kuninkaansa Siionin vuorella siitä alkaen ja iankaikkisesti.',
        8: 'Sinä Karjatorni, tytär Siionin kukkula! Sinun luoksesi tulee ja saapuu entinen hallitus, tytär Jerusalemin kuninkuus.',
        9: 'Nyt – miksi vaikeroit ääneen? Eikö sinulla ole kuningasta, onko sinun neuvonantajasi kadonnut, koska kipu on vallannut sinut kuin synnyttäjän?',
        10: 'Vääntelehdi vain kouristuksissasi, tytär Siion, kuin synnyttäjä, sillä nyt sinun on lähdettävä ulos kaupungista ja asuttava kedolla ja mentävä Baabeliin asti. Siellä sinut pelastetaan. Siellä Herra lunastaa sinut vihamiestesi käsistä.',
        11: 'Nyt kokoontuu sinua vastaan paljon pakanoita, jotka sanovat: "Se saastutettakoon. Katselkoon silmämme Siionia!"',
        12: 'Mutta he eivät tunne Herran ajatuksia eivätkä ymmärrä hänen neuvoaan, sillä hän kokoaa heidät kuin lyhteet puimatantereelle.',
        13: 'Nouse ja pui, tytär Siion, sillä annan sinulle rautasarvet ja vaskisorkat sinulle annan, ja sinä murskaat monet kansat. Vihin Herralle, tuhon omaksi, heidän väärän voittonsa, kaiken maan Herralle heidän rikkautensa.',
        14: 'Nyt yhdy laumaksi, sinä hyökkääjien ahdistama tytär! Meitä piiritetään, he lyövät sauvalla poskelle Israelin tuomaria.',
    },
    5: {
        1: 'Mutta sinä, Beetlehem Efrata, joka olet vähäinen olemaan Juudan sukujen joukossa, sinusta minulle tulee se, joka on oleva hallitsija Israelissa, jonka alkuperä on muinaisuudesta, iankaikkisista päivistä.',
        2: 'Sen tähden Herra antaa heidät alttiiksi siihen aikaan asti, jolloin synnyttäjä on synnyttänyt. Silloin jäljellejääneet hänen veljistään palaavat israelilaisten luo.',
        3: 'Hän on astuva esiin ja kaitseva Herran voimassa, Herran, Jumalansa, nimen valtasuuruudessa. He asuvat alallaan, sillä hän on oleva suuri maan ääriin asti.',
        4: 'Hän on oleva rauha. Kun Assur saapuu maahamme ja kun se tulee palatseihimme, asetamme sitä vastaan seitsemän paimenta ja kahdeksan ruhtinasta.',
        5: 'Nämä kaitsevat miekalla Assurin maata, Nimrodin maata aivan sen omilla porteilla. Hän on pelastava meidät Assurilta, kun se tulee maahamme ja kun se astuu alueellemme.',
        6: 'Ne, jotka ovat jäljellä Jaakobista monien kansojen seassa, ovat kuin kaste Herralta, kuin rankkasade ruohikolle. Se ei odota miestä eikä varro ihmislapsia.',
        7: 'Ne, jotka ovat jäljellä Jaakobista pakanoiden seassa monien kansojen keskellä, ovat kuin leijona metsän eläinten seassa, kuin nuori leijona lammaslaumojen keskellä. Jos se hyökkää, tallaa maahan ja raatelee, pelastajaa ei ole.',
        8: 'Kohotkoon kätesi vihollisiasi vastaan, ja vihamiehesi joutukoot häviöön.',
        9: 'Tapahtuu, että sinä päivänä, – tämä on Herran sana – hävitän keskuudestasi hevosesi ja teen lopun sotavaunuistasi.',
        10: 'Hävitän maasi kaupungit ja hajotan maahan kaikki linnoituksesi.',
        11: 'Hävitän sinulta käsistä povaamisen eikä sinulla ole enää ennustelijoita.',
        12: 'Hävitän keskuudestasi jumalankuvasi ja patsaasi, etkä sinä enää kumarra kättesi tekoa.',
        13: 'Kukistan aserasi keskuudestasi ja tuhoan kaupunkisi.',
        14: 'Kostan vihassa ja kiivaudessa pakanakansoille, jotka eivät olleet kuuliaisia.',
    },
    6: {
        1: 'Kuulkaa, mitä Herra sanoo: Nouse ja käy oikeutta vuorten kanssa, ja kukkulat kuulkoot äänesi.',
        2: 'Kuulkaa Herran oikeudenkäyntiä, vuoret, te iäti kestävät, maan perustukset, sillä oikeudenkäynti on Herralla kansaansa vastaan ja Israelille hän pitää tuomion:',
        3: '"Kansani, mitä olen sinulle tehnyt, ja millä olen sinut väsyttänyt? Vastaa minulle!',
        4: 'Olenhan johdattanut sinut Egyptin maasta, vapahtanut sinut orjuuden pesästä ja lähettänyt Mooseksen, Aaronin ja Mirjamin käymään edelläsi.',
        5: 'Muista, kansani, mitä Baalakilla, Mooabin kuninkaalla, oli mielessä, ja mitä Bileam, Beorin poika, hänelle vastasi, Sittimistä Gilgaliin asti, että käsittäisit Herran vanhurskaat teot."',
        6: '"Mitä uhraan, kun käyn Herran eteen ja kumarrun korkeuden Jumalan puoleen? Käynkö hänen eteensä tuoden polttouhreja, vuodenvanhoja vasikoita?',
        7: 'Ovatko Herralle mieleen tuhannet pässit, kymmenettuhannet öljyvirrat? Annanko esikoiseni rikoksestani ja ruumiini hedelmän sieluni syntiuhriksi?"',
        8: 'Hän on ilmoittanut sinulle, ihminen, mikä hyvä on, ja mitä muuta Herra sinulta vaatii, kuin että teet sitä, mikä on oikein, rakastat laupeutta ja vaellat nöyrästi Jumalasi kanssa?',
        9: 'Herran ääni huutaa kaupungille – ja on ymmärrystä ottaa nimestäsi vaari. Totelkaa vitsaa ja häntä, joka on sen määrännyt.',
        10: 'Vieläkö ovat jumalattoman talossa vääryyden aarteet ja vajaa, kirottu eefa-mitta?',
        11: 'Olisinko puhdas, jos minulla olisi väärä vaaka ja kukkarossa petolliset punnukset?',
        12: 'Sen rikkaat ovat täynnä väkivaltaa, sen asukkaat puhuvat valhetta, kieli heidän suussaan on petollinen.',
        13: 'Niinpä minäkin lyön sinut sairaaksi, teen sinut autioksi syntiesi tähden.',
        14: 'Sinä syöt, mutta et tule ravituksi, ja vatsassasi on tyhjyys. Minkä viet pois, sitä et saa pelastetuksi, ja minkä pelastetuksi saat, sen annan miekan omaksi.',
        15: 'Sinä kylvät, mutta et leikkaa. Sinä puserrat öljyä, mutta et voitele itseäsi öljyllä, ja puserrat rypälemehua, mutta et juo viiniä.',
        16: 'Mutta Omrin ohjeita noudatetaan ja kaikkia Ahabin suvun tekoja. Heidän neuvojensa mukaan te vaellatte, että saattaisin sinut autioksi ja sen asukkaat pilkaksi. Te tulette kantamaan kansani häväistyksen.',
    },
    7: {
        1: 'Voi minua, sillä minun käy kuin hedelmänkorjuussa, kuin viinisadon jälkikorjuussa: ei ole rypälettä syödäkseni, ei varhaisviikunaa, jota sieluni haluaa.',
        2: 'Hävinneet ovat pyhät maasta, eikä oikeamielisiä ole ihmisten joukossa. Kaikki he väijyvät verta ja pyydystävät verkolla toinen toistaan.',
        3: 'Heidän kätensä ovat taitavia tekemään pahaa. Ruhtinas ja tuomari vaativat lahjuksia, ja mahtavat puhuvat julki sielunsa himon ja vääristelevät asian.',
        4: 'Paras heistä on kuin orjantappura, oikeamielisin pahempi kuin teräväokainen aita. Vartijoidesi ilmoittama päivä, kosto sinulle, tulee. Nyt he joutuvat sekasortoon.',
        5: 'Älkää uskoko ystävää, älkää luottako uskottuun. Siltä, joka sylissäsi lepää, varjele suusi ovet.',
        6: 'Sillä poika halveksii isää, tytär nousee äitiään vastaan ja miniä anoppiaan vastaan. Ihmisen vihamiehiä ovat hänen omat perhekuntalaisensa.',
        7: 'Mutta minä panen toivoni Herraan ja odotan pelastukseni Jumalaa. Jumalani on minua kuuleva.',
        8: 'Älkää iloitko, viholliseni, minusta. Jos olen langennut, niin nousen. Jos istun pimeydessä, Herra on valkeuteni.:',
        9: 'Kannan Herran vihaa, sillä olen tehnyt syntiä häntä vastaan, siihen asti, että hän hoitaa riita-asiani ja hankkii minulle oikeuden. Hän tuo minut valkeuteen, ja katselen hänen vanhurskauttaan.',
        10: 'Viholliseni näkevät sen, ja häpeä peittää ne, jotka sanovat minulle: "Missä on Herra, Jumalasi?" Silmäni katselevat heitä. Nyt he joutuvat tallattaviksi kuin katujen loka.',
        11: 'Tulee päivä, jolloin muurisi rakennetaan. Sinä päivänä rajasi on oleva kaukana:',
        12: 'sinä päivänä tullaan luoksesi Assurista ja Egyptin kaupungeista, kaikkialta, Egyptistä aina Eufrat-virtaan, merestä mereen, vuoresta vuoreen.',
        13: 'Mutta tapahtuu, että maa tulee autioksi asukkaittensa tähden, heidän tekojensa hedelmien takia.',
        14: 'Kaitse kansaasi sauvallasi, perintölaumaasi, joka asuu erillään metsässä keskellä Karmelia. Käykööt laitumella Baasanissa ja Gileadissa kuin ennen ikiaikoina. –',
        15: '"Niin kuin Egyptin maasta lähtösi päivinä annan hänen nähdä ihmeitä." –',
        16: 'Sen näkevät pakanakansat ja saavat häpeän kaikesta väkevyydestään. He panevat käden suulleen, heidän korvansa menevät lukkoon.',
        17: 'He nuolevat tomua kuin käärme, kuin maan matelijat. Vavisten he tulevat linnoituksistaan, lähestyvät väristen Herraa, Jumalaamme, ja pelkäävät sinua.',
        18: 'Kuka on Jumala niin kuin sinä, joka annat pahat teot anteeksi ja käyt ohi perintösi jäännöksen rikosten? Ei hän pidä vihaa iäti, sillä hänellä on mielihalu laupeuteen.',
        19: 'Hän armahtaa meitä jälleen, polkee maahan pahat tekomme ja kaikki heidän syntinsä sinä heität meren syvyyteen.',
        20: 'Sinä osoitat Jaakobille uskollisuutta, Aabrahamille armoa, kuten olet vannonut isillemme muinaisista päivistä asti.',
    },
}
